for (const language of Object.keys(extraAccountListingTranslations) as AccountLanguage[]) {
  Object.assign(accountListingTranslations[language], extraAccountListingTranslations[language])
}

export function accountListingText(locale: PublicLocale, en: string, sv?: string) {
  const language = translationLocale(locale) as AccountLanguage
  if (locale === 'sv') return accountListingTranslations.sv[en] || sv || en
  return accountListingTranslations[language]?.[en] || translatePublic(locale, en)
}

export function accountListingObject<T>(locale: PublicLocale, value: T): T {
  if (typeof value === 'string') return accountListingText(locale, value) as T
  if (Array.isArray(value)) return value.map((item) => accountListingObject(locale, item)) as T
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, accountListingObject(locale, item)])) as T
  }
  return value
}
